/** Lab research: one index by category, one page per lab. */
/* ── file map ─────────────────────────────────────────────────────────────────
 * exports    build
 * depends    scripts/game-wiki/render.mjs
 * used by    —
 * ────────────────────────────────────────────────── generated by `pnpm map` ──
 */
import { heading, infobox, sections, table } from '../render.mjs'

export function build(context) {
  const { data } = context.sdk
  const { format } = context
  const labs = data.LAB_CATALOG

  const unlockText = lab => {
    const unlock = data.LAB_UNLOCKS[lab.name]
    if (!unlock) return ''
    if (unlock === data.UNLOCKED_BY_ULTIMATE) return 'With its ultimate weapon'
    return `Tier ${unlock.tier}, wave ${unlock.wave}`
  }

  for (const lab of labs) {
    const rows = lab.levels.map(row => [
      row.level,
      format.value(data.computeLabValueAtLevel(lab, row.level)),
      row.duration,
      format.cost(row.cost),
    ])
    context.page(
      `Lab: ${lab.name}`,
      sections(
        lab.description ?? '',
        infobox([
          ['Category', lab.category],
          ['Levels', lab.levels.length],
          ['Unit', lab.unit],
          ['Unlocks at', unlockText(lab)],
        ]),
        heading(2, 'Levels'),
        table(['Level', 'Value', 'Research time', 'Coin cost'], rows),
        `Back to ${context.link('Labs')}.`,
      ),
      { source: ['LAB_CATALOG', 'LAB_UNLOCKS'] },
    )
  }

  const categories = [...new Set(labs.map(lab => lab.category))].sort()
  context.page(
    'Labs',
    sections(
      context.overview('labs'),
      `${labs.length} labs in ${categories.length} categories.`,
      ...categories.map(category =>
        sections(
          heading(2, category),
          table(
            ['Lab', 'Levels', 'Unlocks at'],
            labs
              .filter(lab => lab.category === category)
              .map(lab => [context.link(`Lab: ${lab.name}`, lab.name), lab.levels.length, unlockText(lab)]),
          ),
        ),
      ),
    ),
    { source: ['LAB_CATALOG', 'LAB_UNLOCKS'] },
  )

  context.group('Labs', ['Labs'])
}
